export function pronunciationRules(language: keyof typeof LANGUAGES) {
  if (language === "ja")
    return "Japanese readings use whole-word hiragana, including okurigana and katakana words; retain long-vowel marks. Never dictionary-guess a source-supplied reading.";
  if (language === "ko")
    return "Korean readings use reliable contextual Hangul without delimiters or punctuation; distinguish general sound changes from actual recorded speech.";
  if (language === "zh-TW")
    return "Taiwan Mandarin readings use Zhuyin with tones ˊ ˇ ˋ and prefixed neutral ˙; syllables separated by spaces. Do not guess polyphonic words or names.";
  if (language === "zh-CN")
    return "Mainland Mandarin readings use tone-marked Hanyu Pinyin with diacritics, never tone numbers; syllables separated by spaces. Do not guess polyphonic words or names.";
  return "Use reliable slash-delimited IPA, never bare spelling. No audio is supplied.";
}
